public function delete(string $fileName): void
{
    $this->assertSupported($fileName);
    $path = $this->getPath($fileName);

    if (!is_file($path)) {
        throw new FileNotFoundException(basename($fileName));
    }

    if (!unlink($path)) {
        throw new StorageException('Could not delete file "' . basename($fileName) . '".');
    }
}

private function assertSupported(string $fileName): void
{
    // throws UnsupportedFormatException for other extensions
    $this->findFileActions($fileName);
}

